#+TITLE: Calendar
#+PROPERTY: header-args:js :noweb yes :results table :tangle no

Run a block with its Run button (or C-c C-c). JavaScript blocks must be turned on in Settings → Editing and startup → Editing.

* This month
No network. Today is shown in brackets.

#+begin_src js
const now = new Date();
const y = now.getFullYear(), m = now.getMonth();
const first = new Date(y, m, 1);
const days = new Date(y, m + 1, 0).getDate();
let col = (first.getDay() + 6) % 7;                 // weeks start on Monday
const rows = [['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']];
let row = Array(col).fill('');
for (let d = 1; d <= days; d++) {
  row.push(d === now.getDate() ? '[' + d + ']' : String(d));
  if (++col === 7) { rows.push(row); row = []; col = 0; }
}
if (row.length) rows.push(row.concat(Array(7 - row.length).fill('')));
return rows;
#+end_src

* Events from a pasted calendar
No network: the calendar text is in the block. Replace it with the contents of an =.ics= file. =org.ics.parse= gives each event's title, start, end, place and repeat (such as =+1w=).

#+begin_src js
const text = `BEGIN:VCALENDAR
BEGIN:VEVENT
SUMMARY:Team lunch
DTSTART:20261016T120000
DTEND:20261016T130000
LOCATION:Cafe
END:VEVENT
BEGIN:VEVENT
SUMMARY:Water the plants
DTSTART;VALUE=DATE:20261012
RRULE:FREQ=WEEKLY
END:VEVENT
END:VCALENDAR`;
const events = await org.ics.parse(text);
return [['Start', 'Title', 'Place', 'Repeats']].concat(
  events.filter((e) => !e.cancelled).sort((a, b) => a.start.localeCompare(b.start)).map((e) => [e.start, e.summary, e.location, e.repeat || '']));
#+end_src

* Events from a calendar feed
Fetches an =.ics= address, keeps it for six hours, and lists what starts in the next =days= days (a repeating event is listed once, from its first date). You are asked once to allow the host. The feed's server must allow reading from a web page; many calendar hosts do not, and then the block says it could not read it.

Replace =feed= and =:net= with your own calendar's address and host.

#+begin_src js :net calendar.google.com :var feed="https://calendar.google.com/calendar/ical/en.usa%23holiday%40group.v.calendar.google.com/public/basic.ics" :var days=60
let text = await org.cache.get('calendar-feed', 6 * 3600e3);
if (text === null) {
  const r = await org.fetch(feed);
  if (!r.ok) return [['Could not read the feed', 'status ' + r.status]];
  text = await org.cache.set('calendar-feed', await r.text());
}
const day = (t) => new Date(t.slice(0, 10) + 'T00:00:00');
const from = new Date(); from.setHours(0, 0, 0, 0);
const to = new Date(from.getTime() + days * 86400000);
const events = (await org.ics.parse(text))
  .filter((e) => !e.cancelled && day(e.start) >= from && day(e.start) < to)
  .sort((a, b) => a.start.localeCompare(b.start));
return [['Start', 'Title', 'Place']].concat(events.map((e) => [e.start, e.summary, e.location]));
#+end_src

* The same feed in the agenda (init script)
Tangles to =init.js= and is not meant to be run with its Run button (it says so if you do). In Settings → Extensions choose *Use an Org file…* and name this file (=local:calendar.org=, =github:...=, =webdav:...=), then approve. The feed's events then appear in the agenda; the agenda asks again after ten minutes.

#+begin_src js :tangle init.js
if (!org.agenda) return 'Not run here: this block is the init script, which only works from Settings → Extensions → Use an Org file….';
const feed = 'https://calendar.google.com/calendar/ical/en.usa%23holiday%40group.v.calendar.google.com/public/basic.ics';
org.agenda.source('holidays', async () => {
  let text = await org.cache.get('calendar-feed', 6 * 3600e3);
  if (text === null) text = await org.cache.set('calendar-feed', await (await org.fetch(feed)).text());
  return (await org.ics.parse(text)).filter((e) => !e.cancelled).map((e) => ({ title: e.summary, start: e.start, end: e.end, repeat: e.repeat }));
});
#+end_src

#+TITLE: Sunrise and sunset
#+PROPERTY: header-args:js :noweb yes :results table :tangle no

Run a block with its Run button (or C-c C-c). JavaScript blocks must be turned on in Settings → Editing and startup → Editing.

The calculation is written once, in the block named =sun=; the others pull it in with =<<sun>>=.

* The calculation
Not run by itself. It finds sunrise and sunset (as Date values) for a day and place, or nothing when the sun does not rise or set.

#+NAME: sun
#+begin_src js :results none
const rad = Math.PI / 180;
const julian = (d) => d / 86400000 + 2440587.5;
function sun(date, lat, lon) {
  const n = Math.ceil(julian(date) - 2451545.0 + 0.0008);
  const Js = n + 0.0009 - lon / 360;              // lon is east-positive
  const M = (357.5291 + 0.98560028 * Js) % 360;
  const C = 1.9148 * Math.sin(M * rad) + 0.02 * Math.sin(2 * M * rad);
  const L = (M + C + 180 + 102.9372) % 360;
  const Jt = 2451545 + Js + 0.0053 * Math.sin(M * rad) - 0.0069 * Math.sin(2 * L * rad);
  const dec = Math.asin(Math.sin(L * rad) * Math.sin(23.4397 * rad));
  const cosW = (Math.sin(-0.833 * rad) - Math.sin(lat * rad) * Math.sin(dec)) / (Math.cos(lat * rad) * Math.cos(dec));
  if (cosW > 1 || cosW < -1) return null;          // polar night or midnight sun
  const w = Math.acos(cosW) / rad;
  const at = (j) => new Date((j - 2440587.5) * 86400000);
  return { rise: at(Jt - w / 360), set: at(Jt + w / 360) };
}
const hhmm = (d) => d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
const length = (s) => {
  const m = Math.round((s.set - s.rise) / 60000);
  return Math.floor(m / 60) + ' h ' + String(m % 60).padStart(2, '0') + ' min';
};
#+end_src

* Today, at the place set in Settings
Uses =calendar-latitude= and =calendar-longitude= (Settings → Agenda, diary and weather → Diary can fill them in from the device).

#+begin_src js
<<sun>>
const lat = Number(org.vars.get('calendar-latitude'));
const lon = Number(org.vars.get('calendar-longitude'));
if (!Number.isFinite(lat) || !Number.isFinite(lon)) return [['Set calendar-latitude and calendar-longitude first']];
const s = sun(new Date(), lat, lon);
if (!s) return [['Sun', 'does not rise or set today']];
return [['Sunrise', hhmm(s.rise)], ['Sunset', hhmm(s.set)], ['Daylight', length(s)]];
#+end_src

* Today, where the phone is
Asks once for permission to read the position (=:location yes=). Nothing is sent anywhere.

#+begin_src js :location yes
<<sun>>
const { lat, lon } = await org.location.get();
const s = sun(new Date(), lat, lon);
if (!s) return [['Sun', 'does not rise or set today']];
return [['Position', lat.toFixed(2) + ', ' + lon.toFixed(2)], ['Sunrise', hhmm(s.rise)], ['Sunset', hhmm(s.set)], ['Daylight', length(s)]];
#+end_src

* The next seven days
Change =days= to look further ahead.

#+begin_src js :var days=7
<<sun>>
const lat = Number(org.vars.get('calendar-latitude'));
const lon = Number(org.vars.get('calendar-longitude'));
if (!Number.isFinite(lat) || !Number.isFinite(lon)) return [['Set calendar-latitude and calendar-longitude first']];
const rows = [['Day', 'Sunrise', 'Sunset', 'Daylight']];
for (let i = 0; i < days; i++) {
  const d = new Date(Date.now() + i * 86400000);
  const s = sun(d, lat, lon);
  const label = d.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
  rows.push(s ? [label, hhmm(s.rise), hhmm(s.set), length(s)] : [label, '-', '-', 'no sunrise or sunset']);
}
return rows;
#+end_src

* A line above the agenda (init script)
This block tangles to =init.js= and is not meant to be run with its Run button (it says so if you do). In Settings → Extensions choose *Use an Org file…* and give this file as =local:sunrise-sunset.org= (or =github:...=, =webdav:...=), then approve it. The agenda then shows "Sunrise 07:12 · Sunset 18:05" above its list. The same calculation is reused through Noweb.

#+begin_src js :tangle init.js
<<sun>>
if (!org.ui) return 'Not run here: this block is the init script, which only works from Settings → Extensions → Use an Org file….';
org.ui.line('sun', () => {
  const lat = Number(org.vars.get('calendar-latitude'));
  const lon = Number(org.vars.get('calendar-longitude'));
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return '';
  const s = sun(new Date(), lat, lon);
  return s ? 'Sunrise ' + hhmm(s.rise) + ' · Sunset ' + hhmm(s.set) : 'The sun does not rise or set today';
});
#+end_src
